// Quick syntax check of the sorting logic
void testSort() {
  final rs = [
    {'מחיר': '5,000', 'שם': 'car1'},
    {'מחיר': '3,500', 'שם': 'car2'},
    {'מחיר': '8,200', 'שם': 'car3'},
  ];

  final rsSorted = [...rs];
  rsSorted.sort((a, b) {
    final priceA = double.tryParse((a['מחיר'] ?? '').replaceAll(RegExp(r'[^0-9.]'), '')) ?? 0;
    final priceB = double.tryParse((b['מחיר'] ?? '').replaceAll(RegExp(r'[^0-9.]'), '')) ?? 0;
    return priceA.compareTo(priceB);
  });

  // Expected order: car2 (3500), car1 (5000), car3 (8200)
  print('Sorted by price:');
  for (var r in rsSorted) {
    print('${r['שם']}: ${r['מחיר']}');
  }
}
EOF
